def solve(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    seeds=[(rr,cc) for rr in range(H) for cc in range(W) if g[rr][cc]==4]
    blk={(rr,cc) for rr in range(H) for cc in range(W) if g[rr][cc]==5}
    # try: start at seed cell adjacent to block? demo3 seed (0,1).. check each seed as starting corner
    best=None
    for srt in seeds:
        for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
            r,c=srt[0]+dr,srt[1]+dc
            if not(0<=r<H and 0<=c<W) or (r,c) in blk: continue
            path=[(r,c)]; v={(r,c)}
            while True:
                nr,nc=r+dr,c+dc
                if not(0<=nr<H and 0<=nc<W): break
                if (nr,nc) in blk:
                    dr,dc=-dr,dc; nr,nc=r+dr,c+dc
                if (nr,nc) in v: break
                v.add((nr,nc)); path.append((nr,nc)); r,c=nr,nc
            key=(len(path)-1, srt, dr, dc)
            if best is None or key>best[0]:
                best=key
            if len(path)>H+W-2: break
    sim=g; 
    sr,sc,dr,dc=tuple(p0:=best[0]),tuple(best[1]),best[2],best[3]
    r,c=sr[0]+dr,sr[1]+dc
    if not(0<=r<H and 0<=c<W): return sim
    path=[(r,c)]
    while True:
        nr,nc=r+dr,c+dc
        if not(0<=nr<H and 0<=nc<W): break
        if (nr,nc) in blk: dr,dc=-dr,dc; continue
        if (r,c)==sr: break
        path.append((nr,nc)); r,c=nr,nc
    for rr,cc in path: sim[rr][cc]=3
    return sim
