def f(g,debug=False):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    seeds=[(rr,cc) for rr in range(H) for cc in range(W) if g[rr][cc]==4]
    bg9={(rr,cc) for rr in range(H) for cc in range(W) if g[rr][cc]==9}
    ds=sorted(seeds)
    dr=(ds[1][0]-ds[0][0])//max(1,len(ds)-1)
    dc=(ds[1][1]-ds[0][1])//max(1,len(ds)-1)
    path=set()
    for st in seeds:
        for sgn in (-1,1):
            d_r,d_c=sgn*dr,sgn*dc
            rr,cc=st[0]+d_r,st[1]+d_c
            steps=[]
            while True:
