                nr,nc=rr+d_r,cc+d_c
                if not(0<=nr<H and 0<=nc<W) or (nr,nc) in bg9: break
                rr,cc=nr,nc
            if len(steps)>H+W: break
    sim=[r[:] for r in g]
    for rr,cc in path: sim[rr][cc]=3
    if debug: print('path=',sorted(path))
    return sim
