import json,math
from collections import Counter

def solve(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for row in I for x in row)
    bg=cnt.most_common(1)[0][0]
    nonbg={v:n for v,n in cnt.items() if v!=bg}
    mcol=min(nonbg,key=lambda v:nonbg[v])
    mk=[(r,c) for r in range(H) for c in range(W) if I[r][c]==mcol]
    # normalize marker direction
    dr=(mk[1][0]-mk[0][0]); dc=(mk[1][1]-mk[0][1])
    g=math.gcd(abs(dr),abs(dc)); dr//=g; dc//=g
    def rot(v): return (v[1],-v[0]) if False else None
    def f90(v): return (-v[1],v[0])   # counter-clockwise
    def isok(r,c): return 0<=r<H and 0<=c<W and I[r][c]==bg
    cands=[]
    for e in (mk[0],mk[-1]):
        for p in [(-dc,dr),(dc,-dr)]:
            s=(e[0]+p[0],e[1]+p[1])
            if isok(*s): cands.append((s,e,p))
    def walk(s,p):
        cur=s; path=[s]; n=0
        while n<2*(H+W):
            nxt=(cur[0]+p[0],cur[1]+p[1]); n+=1
            if not isok(*nxt):
                if 0<=nxt[0]<H and 0<=nxt[1]<W and I[nxt[0]][nxt[1]]!=bg:
                    # reflect: pick rotation whose next step is free
                    took=None
                    for q in (f90(p),(p[0],-p[1])):
                        if isok(cur[0]+q[0],cur[1]+q[1]):
                            took=q; break
                    if took is None: break
                    p=took
                else: break
            cur=nxt; path.append(cur)
        return tuple(path)
    best=None
    for s,e,p in cands:
        path=tuple(walk(s,p))
        # tie-break: prefer path with first-step direction pointing away from marker body
        key=(-len(path), -min(max(s[0]-e[0],e[0]-s[0]), 0) )
        if best is None or key>best[0] or (key==best[0] and len(path)>best[1]):
            best=(key,len(path),path)
    painted=set(best[2])
    out=[row[:] for row in I]
    for r,c in painted: out[r][c]=3
    return out

