import numpy as np
def reflect(g):
    g=np.array(g); H,W=g.shape
    cnt={}
    for r in range(H):
        for c in range(W):
            cnt[g[r][c]]=cnt.get(g[r][c],0)+1
    order=sorted(cnt,key=lambda k:-cnt[k])
    bg=order[0]; wall=order[1]; mk=order[2]
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==mk]
    dr=1 if pts[-1][0]>pts[0][0] else -1
    dc=1 if pts[-1][1]>pts[0][1] else -1
    out=g.copy()
    # reflection: flip the axis that points toward the wall; choose from {flip dr, flip dc}; prefer longer segment? test both
    def run(sd,sc):
        r2,c2=pts[-1]+(sd,sc); seg=[]
        while 0<=r2<H and 0<=c2<W and g[r2][c2]==bg:
            seg.append((r2,c2)); r2,c2=r2+sd,c2+sc
        return seg
    flips=[(dr,-dc),(-dr,dc)]   # try each flip
    chosen=None
    for sd,sc in flips:
        s=run(sd,sc)
        if len(s)>0:
            chosen=(sd,sc); break
    r,c=pts[-1]
    while True:
        nr,nc=r+chosen[0],c+chosen[1]
        if not(0<=nr<H and 0<=nc<W) or g[nr][nc]!=bg: break
        out[nr][nc]=3; r,c=nr,nc
    return out.tolist()

for nm,(gi,go) in (('p7',(i7,o7)),('p8',(i8,o8))):
    print(nm,np.array_equal(np.array(reflect(gi)),np.array(go)))

