G=load()

def solve(g):
    g=np.array(g); H,W=g.shape
    cnt={}
    for r in range(H):
        for c in range(W):
            cnt[g[r][c]]=cnt.get(g[r][c],0)+1
    order=[k for k,_ in sorted(cnt.items(),key=lambda kv:-kv[1])]
    bg,wall,mk=order[0],order[1],order[2]
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==mk]
    dr=1 if pts[-1][0]>pts[0][0] else -1
    dc=1 if pts[-1][1]>pts[0][1] else -1
    out=g.copy()
    r,c=pts[-1]
    def run(sd,sc):
        seg=[]; rr,cc=r+sd,c+sc
        while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
            seg.append((rr,cc)); rr,cc=rr+sd,cc+sc
        return seg
    cand=[run(dr,-dc),run(-dr,dc)]
    # bounce rule: paint ray in direction that continues along the beam line through the last marker
    # beam direction from first to last marker extended past endpoint
    br=pts[-1][0]-pts[-2][0]
    bc=pts[-1][1]-pts[-2][1]
    be = (br,bc)
    best=None
    if list(be) in [(dr,-dc),(-dr,dc)]:
        for s in cand:
            if len(s)>0 and (s[0][0]+be[0]*2,s[0][1]+be[1]*2) in s: continue
            if len(s)>0: best=s; break
    # fallback: extend both rays until edge
    for sd,sc in [(dr,-dc),(-dr,dc)]:
        for r_,c_ in run(sd,sc):
            out[r_][c_]=3
            break
    return out.tolist()
